<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {init,api,asset,upload,client,loginGoogle,homepageLogin,headers} from './api.mjs';import {checkUpload,STATES} from '../shared.mjs';
const storageHealth=ref(null),swipeX=ref(0);const resumeBook=ref(null);const pdfCanvas=ref(null),isPdf=ref(false);let pdfDoc,pdfRender;
const session=ref({}),books=ref([]),folders=ref([]),tab=ref('library'),folder=ref('all'),query=ref(''),sort=ref('new'),busy=ref(false),message=ref(''),error=ref(''),progress=ref(0),email=ref(''),password=ref(''),folderName=ref(''),selectedFolder=ref(''),fileInput=ref(),reader=ref(null),page=ref(1),zoom=ref(1),video=ref(null),pageUrl=ref(''),videoUrl=ref(''),thumbUrls=ref({}),admin=ref(null),shareBook=ref(null),visibility=ref('private'),sharedUsers=ref(''),shareUrl=ref(''),searchTerm=ref(''),searchResults=ref([]),findings=ref([]),sortLabel={new:'최근 수정순',title:'제목순'};
let poll,authSubscription,renderGeneration=0,shareHash='';const demo=new URLSearchParams(location.search).get('demo')==='1'&&['127.0.0.1','localhost'].includes(location.hostname);
const list=computed(()=>books.value.filter(b=>(folder.value==='all'||(folder.value==='none'?!b.folder_id:b.folder_id===folder.value))&&b.title.toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>sort.value==='title'?a.title.localeCompare(b.title,'ko'):b.updated_at.localeCompare(a.updated_at)));
const readyCount=computed(()=>books.value.filter(b=>b.state==='ready').length),storage=computed(()=>books.value.reduce((s,b)=>s+Number(b.source_bytes),0));
const fmt=n=>n>=1073741824?(n/1073741824).toFixed(1)+' GiB':(n/1048576).toFixed(1)+' MiB';const date=s=>new Date(s).toLocaleDateString('ko-KR');
async function run(fn){busy.value=true;error.value='';message.value='';try{return await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){if(demo)return;session.value=await api('session');if(session.value.enabled||session.value.admin){const d=await api('list');books.value=d.books;folders.value=d.folders}else{books.value=[];folders.value=[]}if(session.value.admin&&tab.value==='admin')admin.value=await api('admin')}
async function loadAdmin(){tab.value='admin';if(demo){admin.value={settings:{released:false,max_storage_bytes:0,max_daily_jobs:0,max_daily_delivery_bytes:0,storage_reserved:storage.value},books:books.value.map(b=>({...b,owner_id:'화면 예시 회원'})),groups:[{id:'demo',name:'피엠오피스 회원',effect:'allow'}],usage:[],audit:[]};return}await run(async()=>{admin.value=await api('admin');const r=await fetch('/api/storage-health',{headers:await headers()});if(r.ok)storageHealth.value=await r.json()})}
async function saveFolder(){await run(async()=>{await api('folder_save',{name:folderName.value});folderName.value='';await refresh()})}
async function renameFolder(f){const name=prompt('폴더 이름',f.name);if(name)await run(async()=>{await api('folder_save',{id:f.id,name});await refresh()})}
async function chooseFile(e){const file=e.target.files?.[0];if(!file)return;await run(async()=>{checkUpload(file.name,file.size);if(resumeBook.value&&(resumeBook.value.filename!==file.name||resumeBook.value.source_bytes!==file.size))throw Error('기존 업로드와 같은 파일을 선택해 주세요.');const b=resumeBook.value||await api('create',{filename:file.name,title:file.name.replace(/\.(pdf|pptx)$/i,''),bytes:file.size,folder_id:selectedFolder.value||null});resumeBook.value=b;progress.value=0;await refresh();await upload(b.id,file,n=>progress.value=n);resumeBook.value=null;message.value='업로드했습니다. PC 변환 프로그램 실행 중에 순서대로 처리합니다.';await refresh()});e.target.value=''}
async function openBook(b){await run(async()=>{reader.value=await api('get',{book_id:b.id,share_hash:shareHash});tab.value='reader';page.value=1;zoom.value=1;findings.value=[];const textAsset=reader.value.assets.find(a=>a.kind==='text');if(textAsset)findings.value=JSON.parse(await (await asset(b.id,textAsset.id,shareHash)).text());await renderPage();await loadThumbs()})}
function revokeMedia(){video.value?.pause();for(const v of [pageUrl.value,videoUrl.value,...Object.values(thumbUrls.value)])if(v)URL.revokeObjectURL(v);pageUrl.value='';videoUrl.value='';thumbUrls.value={}}
async function renderPage(){const generation=++renderGeneration;video.value?.pause();for(const key of ['pageUrl','videoUrl']){const r=key==='pageUrl'?pageUrl:videoUrl;if(r.value)URL.revokeObjectURL(r.value);r.value=''}const b=reader.value;if(!b)return;
 const still=b.assets.find(a=>a.kind==='page'&&a.page===page.value),movie=b.assets.find(a=>a.kind==='video'&&a.page===page.value);if(still){const blob=await asset(b.id,still.id,shareHash);if(generation!==renderGeneration)return;isPdf.value=still.mime==='application/pdf';if(isPdf.value){await nextTick();pdfRender?.cancel();if(pdfDoc)await pdfDoc.destroy();const lib=await import(/* @vite-ignore */ '/pdfjs/pdf.mjs');lib.GlobalWorkerOptions.workerSrc='/pdfjs/pdf.worker.mjs';pdfDoc=await lib.getDocument({data:new Uint8Array(await blob.arrayBuffer()),isEvalSupported:false,cMapUrl:'/cmaps/',cMapPacked:true,standardFontDataUrl:'/standard_fonts/',wasmUrl:'/wasm/'}).promise;const pg=await pdfDoc.getPage(1),viewport=pg.getViewport({scale:1.7}),canvas=pdfCanvas.value;canvas.width=viewport.width;canvas.height=viewport.height;pdfRender=pg.render({canvasContext:canvas.getContext('2d'),viewport});await pdfRender.promise;}else pageUrl.value=URL.createObjectURL(blob)}
 if(movie){const blob=await asset(b.id,movie.id,shareHash);if(generation!==renderGeneration)return;videoUrl.value=URL.createObjectURL(blob)}
}
async function loadThumbs(){for(const a of reader.value.assets.filter(a=>a.kind==='thumbnail')){if(!reader.value||a.book_id!==reader.value.id)return;thumbUrls.value[a.page]=URL.createObjectURL(await asset(a.book_id,a.id,shareHash))}}
async function navigate(n){if(!reader.value||n<1||n>reader.value.pages)return;page.value=n;await run(renderPage)}
function exitReader(){++renderGeneration;revokeMedia();reader.value=null;tab.value='library';history.replaceState(null,'','/')}
function search(){const term=searchTerm.value.trim().toLowerCase();searchResults.value=term?findings.value.filter(x=>x.text.toLowerCase().includes(term)):[]}
async function download(b){await run(async()=>{const d=await api('get',{book_id:b.id}),a=d.assets.find(a=>a.kind==='source');if(!a)throw Error('원본을 내려받을 수 없습니다.');const blob=await asset(b.id,a.id);const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=b.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function archive(b){if(!confirm('열람과 공유를 중지하고 관리자 보관함으로 옮기시겠습니까?'))return;await run(async()=>{await api('archive',{book_id:b.id});await refresh();if(tab.value==='admin')admin.value=await api('admin')})}
async function approve(b){await run(async()=>{await api('approve',{book_id:b.id});await refresh();message.value='검토를 완료했습니다. 이제 공유 범위를 설정할 수 있습니다.'})}
async function move(b){const name=prompt('이동할 폴더 이름을 입력하세요. 폴더 없이 보관하려면 비워 두세요.','');if(name===null)return;const f=folders.value.find(x=>x.name===name);if(name&&!f){error.value='먼저 해당 폴더를 만들어 주세요.';return}await run(async()=>{await api('update',{book_id:b.id,title:b.title,folder_id:f?.id||null});await refresh()})}
function openShare(b){shareBook.value=b;visibility.value=b.visibility;sharedUsers.value=(b.shared_users||[]).join(', ');shareUrl.value='';if(!demo)run(async()=>{const full=await api('get',{book_id:b.id});sharedUsers.value=(full.shared_users||[]).join(', ')})}
async function saveShare(){await run(async()=>{const result=await api('share',{book_id:shareBook.value.id,visibility:visibility.value,shared_users:sharedUsers.value.split(/[\s,]+/).filter(Boolean)});shareUrl.value='https://ebooks.pmoffice.co.kr/book/'+shareBook.value.id+(result.share_token?'#share='+result.share_token:'');await refresh();message.value='공유 설정을 저장했습니다.'})}
async function groupPolicy(g,effect){await run(async()=>admin.value=await api('group_policy',{group_id:g.id,effect}))}
async function saveSettings(){await run(async()=>{admin.value=await api('settings',admin.value.settings);message.value='운영 한도를 저장했습니다.';await refresh()})}
async function loginEmail(){await run(async()=>{const {error:e}=await client.auth.signInWithPassword({email:email.value,password:password.value});password.value='';if(e)throw Error('이메일과 비밀번호를 확인해 주세요.');await refresh()})}
async function logout(){await run(async()=>{await client.auth.signOut();books.value=[];session.value={};exitReader()})}
function retryUpload(b){resumeBook.value=b;fileInput.value.click()}
async function renameBook(b){const title=prompt('이북 제목',b.title);if(title)await run(async()=>{await api('update',{book_id:b.id,title,folder_id:b.folder_id});await refresh()})}
function key(e){if(tab.value!=='reader'||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')navigate(page.value+1);if(e.key==='ArrowLeft')navigate(page.value-1)}
onMounted(()=>run(async()=>{if(demo){session.value={member:true,enabled:true,admin:true,released:false};folders.value=[{id:'pm',name:'프로젝트 관리'},{id:'ai',name:'AI 교육 자료'}];books.value=[{id:'demo1',title:'프로젝트 관리 실무 가이드',filename:'PM.pdf',format:'pdf',source_bytes:12600000,state:'ready',visibility:'private',pages:48,folder_id:'pm',updated_at:'2026-10-31T03:00:00Z'},{id:'demo2',title:'생성형 AI 업무 활용',filename:'AI.pptx',format:'pptx',source_bytes:24000000,state:'queued',visibility:'private',folder_id:'ai',updated_at:'2026-10-31T02:00:00Z'},{id:'demo3',title:'공정표 작성과 진도 관리',filename:'Schedule.pptx',format:'pptx',source_bytes:18400000,state:'review',visibility:'private',pages:32,folder_id:'pm',updated_at:'2026-10-30T22:00:00Z'}];message.value='화면 검토용 예시 데이터입니다. 실제 회원·파일이 아닙니다.';return}
 await init();authSubscription=client.auth.onAuthStateChange(()=>setTimeout(()=>run(refresh),0)).data.subscription;await refresh();const match=/^\/book\/([0-9a-f-]{36})$/.exec(location.pathname);const token=new URLSearchParams(location.hash.slice(1)).get('share');if(token){shareHash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token)))].map(x=>x.toString(16).padStart(2,'0')).join('');sessionStorage.setItem('ebook-share:'+location.pathname,shareHash);history.replaceState(null,'',location.pathname)}else shareHash=sessionStorage.getItem('ebook-share:'+location.pathname)||'';if(match)await openBook({id:match[1]});const back=sessionStorage.getItem('ebook-return');if(back){sessionStorage.removeItem('ebook-return');if(back.startsWith('/book/'))location.assign(back)}poll=setInterval(()=>{if(tab.value==='library')refresh().catch(()=>{})},30000);window.addEventListener('keydown',key)
}));onUnmounted(()=>{clearInterval(poll);authSubscription?.unsubscribe();window.removeEventListener('keydown',key);revokeMedia()});
</script>
<template>
 <div class="app-shell">
  <aside class="sidebar"><a class="brand" href="https://pmoffice.co.kr"><span class="brand-mark">P</span><span>PMOffice<small>피엠오피스</small></span></a><div class="product-label">E-BOOK STUDIO</div><nav aria-label="이북 서비스"><button :class="{active:tab==='library'}" @click="exitReader">▤ <span>내 이북</span><em>{{books.length}}</em></button><button :class="{active:tab==='guide'}" @click="tab='guide'">ⓘ <span>이용 안내</span></button><button v-if="session.admin" :class="{active:tab==='admin'}" @click="loadAdmin">⚙ <span>시스템 관리</span></button></nav><div v-if="session.enabled" class="folder-section"><p>내 폴더</p><button @click="folder='all';tab='library'" :class="{selected:folder==='all'}">▦ 전체 이북</button><button @click="folder='none';tab='library'" :class="{selected:folder==='none'}">▱ 폴더 없는 이북</button><div v-for="f in folders" :key="f.id" class="folder-row"><button @click="folder=f.id;tab='library'" :class="{selected:folder===f.id}">▱ {{f.name}}</button><button class="edit-folder" aria-label="폴더 이름 변경" @click="renameFolder(f)">✎</button></div><form @submit.prevent="saveFolder" class="new-folder"><input v-model="folderName" placeholder="새 폴더 이름" aria-label="새 폴더 이름" maxlength="120" required><button aria-label="폴더 생성" :disabled="busy||demo">＋</button></form></div><div class="sidebar-bottom"><span class="tiny-label">나의 작업 공간</span><strong>{{books.length}} <small>/ 10권</small></strong><div class="meter"><i :style="{width:books.length*10+'%'}"></i></div><p>원본 {{fmt(storage)}}<br>변환 결과는 관리자 사용량에 포함됩니다.</p><a href="https://pmoffice.co.kr">홈페이지로 돌아가기 ↗</a></div></aside>
  <div class="workspace"><header class="topbar"><span>피엠오피스 <b>/</b> E-book 생성기</span><div class="account-chip"><span class="status-dot"></span>{{session.member?'회원 작업 공간':'이북 서비스'}}<button v-if="session.member&&!demo" @click="logout">로그아웃</button></div></header>
  <main><div v-if="error" role="alert" class="notice error">{{error}}</div><div v-if="message" role="status" class="notice">{{message}}</div><div v-if="!session.released" class="pilot-banner"><span>시험 운영 준비</span>대표 자료 검증과 무료 운영 한도를 확정한 뒤 고객에게 공개합니다.</div>
   <template v-if="tab==='library'">
    <div class="heading"><div><p class="eyebrow">MY PUBLICATIONS</p><h1>내 이북</h1><p>자료를 책으로 만들고, 필요한 사람과 나누세요.</p></div><button class="primary" :disabled="busy||!session.enabled||demo" @click="resumeBook=null;fileInput.click()">＋ 이북 만들기</button><input ref="fileInput" type="file" accept=".pdf,.pptx" hidden @change="chooseFile"></div>
    <section v-if="!session.member&&!demo" class="login-panel"><div><h2>피엠오피스 계정으로 시작하세요</h2><p>기존 Google 또는 이메일 계정을 그대로 이용합니다.</p><button class="primary" @click="run(async()=>{await homepageLogin();await refresh()})">홈페이지 로그인 연결</button><button @click="run(loginGoogle)">Google로 계속하기</button><a href="https://pmoffice.co.kr/signup.html">회원 가입 ↗</a></div><form @submit.prevent="loginEmail"><label>이메일<input type="email" v-model="email" autocomplete="username" required></label><label>비밀번호<input type="password" v-model="password" autocomplete="current-password" required></label><button :disabled="busy">이메일로 로그인</button></form></section>
    <div v-else-if="!session.enabled" class="empty"><h2>서비스 이용 권한을 확인해 주세요.</h2><p>회원 상태 또는 소속 그룹의 이용 정책에 따라 접근이 제한될 수 있습니다.</p></div>
    <section class="summary-row"><div><span>전체 이북</span><strong>{{books.length}}<small>권</small></strong></div><div><span>이용 가능</span><strong>{{readyCount}}<small>권</small></strong></div><div><span>처리·검토 중</span><strong>{{books.filter(b=>['queued','processing','review'].includes(b.state)).length}}<small>권</small></strong></div><div class="limit-note"><span class="document-icon">▧</span><p><b>PDF · PowerPoint</b><br>파일당 50 MiB · 최대 200쪽</p></div></section>
    <div v-if="busy&&progress>0" class="upload-progress" role="progressbar" :aria-valuenow="progress" aria-valuemin="0" aria-valuemax="100"><i :style="{width:progress+'%'}"></i>업로드 {{progress}}%</div>
    <div class="library-tools"><div class="search"><span>⌕</span><input v-model="query" aria-label="이북 제목 검색" placeholder="이북 제목 검색"></div><label>정렬 <select v-model="sort"><option value="new">최근 수정순</option><option value="title">제목순</option></select></label><label>업로드 폴더 <select v-model="selectedFolder"><option value="">폴더 없이 보관</option><option v-for="f in folders" :value="f.id">{{f.name}}</option></select></label></div>
    <div v-if="list.length" class="book-grid"><article v-for="(b,i) in list" :key="b.id" class="book-card"><button class="cover" :class="['cover-'+i%4,b.format]" @click="!demo&&openBook(b)" :aria-label="b.title+' 열기'"><span class="cover-type">{{b.format==='pdf'?'PDF DOCUMENT':'POWERPOINT'}}</span><span class="cover-rule"></span><strong>{{b.title}}</strong><span class="cover-bottom">PMOFFICE <span>{{b.format==='pptx'?'▶ SLIDE VIDEO':'E-BOOK'}}</span></span><span class="book-spine"></span></button><div class="book-info"><div class="book-meta"><span class="badge" :class="b.state">{{STATES[b.state]}}</span><span class="visibility">{{{private:'비공개',members:'지정 회원',link:'링크 공유',public:'전체 공개'}[b.visibility]}}</span></div><h2>{{b.title}}</h2><p>{{b.pages?b.pages+'쪽 · ':''}}{{fmt(b.source_bytes)}} <span>·</span> {{date(b.updated_at)}}</p><div class="card-actions"><button @click="!demo&&openBook(b)">열기 ↗</button><button v-if="b.state==='ready'" @click="openShare(b)">공유</button><button v-if="b.state==='review'" @click="!demo&&approve(b)">검토 완료</button><details><summary aria-label="이북 추가 작업">•••</summary><div><button v-if="b.state==='uploading'" @click="!demo&&retryUpload(b)">업로드 이어하기</button><button @click="!demo&&renameBook(b)">제목 변경</button><button @click="!demo&&move(b)">폴더 이동</button><button @click="!demo&&download(b)">원본 다운로드</button><button @click="!demo&&archive(b)">삭제·관리자 보관</button><a :href="'/book/'+b.id">고정 주소 열기</a></div></details></div></div></article></div>
    <div v-else class="empty"><span>▤</span><h2>첫 이북을 만들어 보세요</h2><p>PDF 또는 PowerPoint를 올리면 내 자료를 온라인 이북으로 관리할 수 있습니다.</p></div>
    <p class="library-footnote">자료는 기본적으로 본인만 볼 수 있습니다. 공유 범위는 이북별로 설정하세요.</p>
   </template>
   <template v-if="tab==='reader'&&reader"><div class="reader-heading"><button @click="exitReader">← 내 이북</button><h1>{{reader.title}}</h1><span>{{page}} / {{reader.pages}}</span></div><div v-if="reader.warnings?.length" class="notice">검토 안내: {{reader.warnings.join(' · ')}}</div><div class="reader-layout"><aside class="thumbnails" aria-label="페이지 썸네일"><button v-for="n in reader.pages" :key="n" :class="{current:n===page}" @click="navigate(n)"><img v-if="thumbUrls[n]" :src="thumbUrls[n]" alt=""><span>{{n}}</span></button></aside><section class="page-stage"><div class="page-toolbar"><button @click="navigate(page-1)" :disabled="page<=1">이전</button><label>페이지 <input type="number" :value="page" min="1" :max="reader.pages" @change="navigate(Number($event.target.value))"></label><button @click="navigate(page+1)" :disabled="page>=reader.pages">다음</button><button aria-label="축소" @click="zoom=Math.max(.5,zoom-.25)">−</button><span>{{Math.round(zoom*100)}}%</span><button aria-label="확대" @click="zoom=Math.min(3,zoom+.25)">＋</button></div><div class="page-scroll" @touchstart="swipeX=$event.changedTouches[0].screenX" @touchend="zoom===1 &amp;&amp; Math.abs($event.changedTouches[0].screenX-swipeX)>60 &amp;&amp; navigate(page+($event.changedTouches[0].screenX<swipeX?1:-1))"><canvas :key="page" v-show="isPdf" ref="pdfCanvas" class="page-image" :style="{width:zoom*100+'%'}" aria-label="이북 페이지"></canvas><img v-if="pageUrl&&!isPdf" class="page-image" :src="pageUrl" :alt="reader.title+' '+page+'쪽'" :style="{width:zoom*100+'%'}"></div><div v-if="videoUrl" class="slide-video"><h2>이 페이지 발표 영상</h2><video ref="video" :src="videoUrl" controls playsinline preload="metadata" :poster="pageUrl"></video><p>재생 버튼을 누르면 애니메이션·음성을 볼 수 있습니다.</p></div><form class="reader-search" @submit.prevent="search"><input v-model="searchTerm" aria-label="본문 검색" :placeholder="reader.searchable?'본문에서 찾기':'이 문서는 검색 가능한 텍스트가 없습니다.'" :disabled="!reader.searchable"><button :disabled="!reader.searchable">찾기</button></form><button v-for="hit in searchResults" class="search-hit" @click="navigate(hit.page)">{{hit.page}}쪽 · {{hit.text.slice(0,100)}}</button></section></div></template>
   <template v-if="tab==='admin'"><div class="heading"><div><p class="eyebrow">SYSTEM MANAGEMENT</p><h1>이북 서비스 관리</h1><p>회원 자료·공유 주소·처리 상태와 운영 한도를 관리합니다.</p></div></div><template v-if="admin"><section class="admin-panel"><h2>운영 한도와 공개 상태</h2><p>대표 자료와 부하 시험 결과를 기준으로 값을 확정하세요. 보관함도 저장량에 포함됩니다.</p><div class="settings-grid"><label>전체 저장량 상한 (bytes)<input type="number" min="0" v-model.number="admin.settings.max_storage_bytes"></label><label>일일 변환 건수<input type="number" min="0" v-model.number="admin.settings.max_daily_jobs"></label><label>일일 전송량 상한 (bytes)<input type="number" min="0" v-model.number="admin.settings.max_daily_delivery_bytes"></label><label>고객 공개<input type="checkbox" v-model="admin.settings.released"></label></div><p>예약·보관량 {{fmt(admin.settings.storage_reserved)}} / 한도 {{fmt(admin.settings.max_storage_bytes)}}</p><button class="primary" @click="saveSettings" :disabled="busy||demo">설정 저장</button></section><section class="admin-panel"><h2>그룹별 이용 정책</h2><p>다중 그룹의 차단 정책을 우선 적용하며 소유자의 공유 이북도 중지됩니다.</p><div v-for="g in admin.groups" class="group-policy"><strong>{{g.name}}</strong><select :disabled="demo" :value="g.effect" @change="groupPolicy(g,$event.target.value)"><option value="allow">허용</option><option value="deny">차단</option></select></div></section><section class="admin-panel"><h2>전체 자료·관리자 보관함</h2><div class="table-scroll"><table><thead><tr><th>이북·소유자</th><th>상태</th><th>원본</th><th>결과 URL</th><th>관리</th></tr></thead><tbody><tr v-for="b in admin.books"><td><b>{{b.title}}</b><small>{{b.owner_id}}</small></td><td>{{STATES[b.state]}}</td><td><button :disabled="demo" @click="download(b)">{{b.filename}}</button></td><td><a :href="'/book/'+b.id" target="_blank" rel="noopener">이북 열기 ↗</a></td><td><button v-if="b.state!=='archived'" :disabled="demo" @click="archive(b)">보관</button></td></tr></tbody></table></div></section><section class="admin-panel"><h2>GitHub 저장소·API 현황</h2><p v-if="storageHealth">비공개 저장소 · GitHub 보고 크기 {{storageHealth.sizeKiB}} KiB · API 잔여 {{storageHealth.core.remaining}} / {{storageHealth.core.limit}} · 갱신 {{new Date(storageHealth.core.reset*1000).toLocaleString('ko-KR')}}</p><p v-else>운영 GitHub 연결 후 저장소 크기와 API 잔여량을 확인할 수 있습니다.</p><h2>최근 사용량</h2><p v-for="u in admin.usage">{{u.day}} · 변환 {{u.jobs}}건 · 전송 {{fmt(u.delivery_bytes)}}</p><h2>변경·열람 이력</h2><p v-for="a in admin.audit.slice(0,30)" class="audit-line">{{new Date(a.created_at).toLocaleString('ko-KR')}} · {{a.action}} · {{a.actor_id||'비회원'}}</p></section></template></template>
   <section v-if="tab==='guide'" class="guide"><p class="eyebrow">GETTING STARTED</p><h1>자료에서 이북까지</h1><ol><li><h2>폴더를 만들고 자료를 올리세요</h2><p>PDF·PPTX, 50 MiB·200쪽 이하 파일을 회원당 10권까지 관리합니다.</p></li><li><h2>변환 결과를 확인하세요</h2><p>PC 변환 프로그램이 실행 중일 때 처리됩니다. PPTX는 페이지 이미지와 페이지별 발표 영상으로 만들어집니다. 영상·음성·애니메이션을 확인한 뒤 검토 완료를 선택하세요.</p></li><li><h2>필요한 사람에게 공유하세요</h2><p>비공개를 기본으로 지정 회원·링크 공유·전체 공개를 선택합니다. 지정 회원은 내부 회원 ID로 등록합니다. 원본은 소유자·관리자만 내려받을 수 있습니다.</p></li><li><h2>자료와 이용량을 관리하세요</h2><p>삭제는 열람을 중지하고 관리자 보관함으로 이동합니다. 무료 한도에 도달하면 신규 업로드·변환·전송이 제한될 수 있습니다.</p></li></ol></section>
  </main><footer>PMOffice <span>내 자료를 더 편하게 읽는 방법</span><a href="https://pmoffice.co.kr/contact.html">이용 문의 ↗</a></footer></div>
  <div v-if="shareBook" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="share-heading"><h2 id="share-heading">이북 공유</h2><p>{{shareBook.title}}</p><label>열람 범위<select v-model="visibility"><option value="private">나만 보기</option><option value="members">지정 회원</option><option value="link">링크를 가진 누구나</option><option value="public">전체 공개</option></select></label><label v-if="visibility==='members'">허용 회원 ID (쉼표로 구분)<textarea v-model="sharedUsers" placeholder="회원 ID를 입력하세요"></textarea></label><p v-if="visibility==='link'">저장할 때 새 공유 링크가 발급되며 이전 링크는 중지됩니다.</p><input v-if="shareUrl" :value="shareUrl" readonly aria-label="공유 URL" @focus="$event.target.select()"><div class="modal-actions"><button @click="shareBook=null">닫기</button><button class="primary" @click="!demo&&saveShare()" :disabled="busy||demo">설정 저장</button></div></section></div>
 </div>
</template>
